import{_ as n,a0 as l,w as p,s as d,I as e,x as i,a1 as a,A as o,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const B=JSON.parse('{"title":"Bootiso ：让你安全地创建 USB 启动设备 | LCTT x X-CMD","titleTemplate":false,"description":"Bootiso ：让你安全地创建 USB 启动设备 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bootiso ：让你安全地创建 USB 启动设备 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bootiso ：让你安全地创建 USB 启动设备 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180410 Bootiso Lets You Safely Create Bootable USB Drive","title":"Bootiso ：让你安全地创建 USB 启动设备","tag":"201805","desc":""},"relativePath":"201805/20180410 Bootiso Lets You Safely Create Bootable USB Drive.md","filePath":"[post].md"}'),b={name:"201805/20180410 Bootiso Lets You Safely Create Bootable USB Drive.md"};function h(g,s,c,u,k,f){const t=l("Link");return p(),d("div",null,[s[30]||(s[30]=e("h1",{id:"bootiso-让你安全地创建-usb-启动设备",tabindex:"-1"},[i("Bootiso ：让你安全地创建 USB 启动设备 "),e("a",{class:"header-anchor",href:"#bootiso-让你安全地创建-usb-启动设备","aria-label":"Permalink to “Bootiso ：让你安全地创建 USB 启动设备”"},"​")],-1)),s[31]||(s[31]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/04/USB-drive-720x340.png",alt:""})],-1)),e("p",null,[s[1]||(s[1]=i("你好，新兵！你们有些人经常使用 ",-1)),s[2]||(s[2]=e("code",null,"dd",-1)),s[3]||(s[3]=i(" 命令做各种各样的事，比如创建 USB 启动盘或者克隆硬盘分区。不过请牢记，",-1)),s[4]||(s[4]=e("code",null,"dd",-1)),s[5]||(s[5]=i(" 是一个危险且有毁灭性的命令。如果你是个 Linux 的新手，最好避免使用 ",-1)),s[6]||(s[6]=e("code",null,"dd",-1)),s[7]||(s[7]=i(" 命令。如果你不知道你在做什么，你可能会在几分钟里把硬盘擦掉。从原理上说，",-1)),s[8]||(s[8]=e("code",null,"dd",-1)),s[9]||(s[9]=i(" 只是从 ",-1)),s[10]||(s[10]=e("code",null,"if",-1)),s[11]||(s[11]=i(" 读取然后写到 ",-1)),s[12]||(s[12]=e("code",null,"of",-1)),s[13]||(s[13]=i(" 上。它才不管往哪里写呢。它根本不关心那里是否有分区表、引导区、家目录或是其他重要的东西。你叫它做什么它就做什么。可以使用像 ",-1)),a(t,{href:"https://www.ostechnix.com/etcher-beauitiful-app-create-bootable-sd-cards-usb-drives/"},{default:o(()=>[...s[0]||(s[0]=[i("Etcher",-1)])]),_:1}),s[14]||(s[14]=i(" 这样的用户友好的应用来代替它。这样你就可以在创建 USB 引导设备之前知道你将要格式化的是哪块盘。",-1))]),s[32]||(s[32]=r(`<p>今天，我发现了另一个可以安全创建 USB 引导设备的工具 Bootiso 。它实际上是一个 BASH 脚本，但真的很智能！它有很多额外的功能来帮我们安全创建 USB 引导盘。如果你想确保你的目标是 USB 设备（而不是内部驱动器），或者如果你想检测 USB 设备，你可以使用 Bootiso。下面是使用此脚本的显著优点:</p><ul><li>如果只有一个 USB 驱动器，Bootiso 会自动选择它。</li><li>如果有一个以上的 USB 驱动器存在，它可以让你从列表中选择其中一个。</li><li>万一你错误地选择一个内部硬盘驱动器，它将退出而不做任何事情。</li><li>它检查选定的 ISO 是否具有正确的 MIME 类型。如果 MIME 类型不正确，它将退出。</li><li>它判定所选的项目不是分区，如果判定失败则退出。</li><li>它将在擦除和对 USB 驱动器分区之前提示用户确认。</li><li>列出可用的 USB 驱动器。</li><li>安装 syslinux 引导系统 (可选)。</li><li>自由且开源。</li></ul><h3 id="使用-bootiso-安全地创建-usb-驱动器" tabindex="-1">使用 Bootiso 安全地创建 USB 驱动器 <a class="header-anchor" href="#使用-bootiso-安全地创建-usb-驱动器" aria-label="Permalink to “使用 Bootiso 安全地创建 USB 驱动器”">​</a></h3><p>安装 Bootiso 非常简单。用这个命令下载最新版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -L https://rawgit.com/jsamr/bootiso/latest/bootiso -O</span></span></code></pre></div><p>把下载的文件加到 <code>$PATH</code> 目录中，比如 <code>/usr/local/bin/</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cp bootiso /usr/local/bin/</span></span></code></pre></div><p>最后，添加运行权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod +x /usr/local/bin/bootiso</span></span></code></pre></div><p>搞定！现在就可以创建 USB 引导设备了。首先，让我们用命令看看现在有哪些 USB 驱动器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -l</span></span></code></pre></div><p>输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Listing USB drives available in your system:</span></span>
<span class="line"><span>NAME HOTPLUG SIZE STATE TYPE</span></span>
<span class="line"><span>sdb 1 7.5G running disk</span></span></code></pre></div><p>如你所见，我只有一个 USB 驱动器。让我们继续通过命令用 ISO 文件创建 USB 启动盘：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso bionic-desktop-amd64.iso</span></span></code></pre></div><p>这个命令会提示你输入 <code>sudo</code> 密码。输入密码并回车来安装缺失的组件（如果有的话），然后创建 USB 启动盘。</p><p>输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[...]</span></span>
<span class="line"><span>Listing USB drives available in your system:</span></span>
<span class="line"><span>NAME HOTPLUG SIZE STATE TYPE</span></span>
<span class="line"><span>sdb 1 7.5G running disk</span></span>
<span class="line"><span>Autoselecting \`sdb&#39; (only USB device candidate)</span></span>
<span class="line"><span>The selected device \`/dev/sdb&#39; is connected through USB.</span></span>
<span class="line"><span>Created ISO mount point at \`/tmp/iso.c5m&#39;</span></span>
<span class="line"><span>\`bootiso&#39; is about to wipe out the content of device \`/dev/sdb&#39;.</span></span>
<span class="line"><span>Are you sure you want to proceed? (y/n)&gt;y</span></span>
<span class="line"><span>Erasing contents of /dev/sdb...</span></span>
<span class="line"><span>Creating FAT32 partition on \`/dev/sdb1&#39;...</span></span>
<span class="line"><span>Created USB device mount point at \`/tmp/usb.QgV&#39;</span></span>
<span class="line"><span>Copying files from ISO to USB device with \`rsync&#39;</span></span>
<span class="line"><span>Synchronizing writes on device \`/dev/sdb&#39;</span></span>
<span class="line"><span>\`bootiso&#39; took 303 seconds to write ISO to USB device with \`rsync&#39; method.</span></span>
<span class="line"><span>ISO succesfully unmounted.</span></span>
<span class="line"><span>USB device succesfully unmounted.</span></span>
<span class="line"><span>USB device succesfully ejected.</span></span>
<span class="line"><span>You can safely remove it !</span></span></code></pre></div><p>如果你的 ISO 文件 MIME 类型不对，你会得到下列错误信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Provided file \`bionic-desktop-amd64.iso&#39; doesn&#39;t seem to be an iso file (wrong mime type: \`application/octet-stream&#39;).</span></span>
<span class="line"><span>Exiting bootiso...</span></span></code></pre></div><p>当然，你也能像下面那样使用 <code>–no-mime-check</code> 选项来跳过 MIME 类型检查。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso --no-mime-check bionic-desktop-amd64.iso</span></span></code></pre></div><p>就像我前面提到的，如果系统里只有 1 个 USB 设备 Bootiso 将自动选中它。所以我们不需要告诉它 USB 设备路径。如果你连接了多个设备，你可以像下面这样使用 <code>-d</code> 来指明 USB 设备。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -d /dev/sdb bionic-desktop-amd64.iso</span></span></code></pre></div><p>用你自己的设备路径来换掉 <code>/dev/sdb</code>。</p><p>在多个设备情况下，如果你没有使用 <code>-d</code> 来指明要使用的设备，Bootiso 会提示你选择可用的 USB 设备。</p><p>Bootiso 在擦除和改写 USB 盘分区前会要求用户确认。使用 <code>-y</code> 或 <code>–assume-yes</code> 选项可以跳过这一步。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -y bionic-desktop-amd64.iso</span></span></code></pre></div><p>您也可以把自动选择 USB 设备与 <code>-y</code> 选项连用，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -y -a bionic-desktop-amd64.iso</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso?--assume-yes?--autoselect bionic-desktop-amd64.iso</span></span></code></pre></div><p>请记住，当你只连接一个 USB 驱动器时，它才会起作用。</p><p>Bootiso 会默认创建一个 FAT 32 分区，挂载后用 <code>rsync</code> 程序把 ISO 的内容拷贝到 USB 盘里。 如果你愿意也可以使用 <code>dd</code> 代替 <code>rsync</code> 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso --dd -d /dev/sdb bionic-desktop-amd64.iso</span></span></code></pre></div><p>如果你想增加 USB 引导的成功概率，请使用 <code>-b</code> 或 <code>–bootloader</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -b bionic-desktop-amd64.iso</span></span></code></pre></div><p>上面这条命令会安装 <code>syslinux</code> 引导程序（安全模式）。注意，此时 <code>–dd</code> 选项不可用。</p><p>在创建引导设备后，Bootiso 会自动弹出 USB 设备。如果不想自动弹出，请使用 <code>-J</code> 或 <code>–no-eject</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -J bionic-desktop-amd64.iso</span></span></code></pre></div><p>现在，USB 设备依然连接中。你可以使用 <code>umount</code> 命令随时卸载它。</p><p>需要完整帮助信息，请输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bootiso -h</span></span></code></pre></div><p>好，今天就到这里。希望这个脚本对你有帮助。好货不断，不要走开哦！</p><hr>`,45)),e("p",null,[s[16]||(s[16]=i("via: ",-1)),a(t,{href:"https://www.ostechnix.com/bootiso-lets-you-safely-create-bootable-usb-drive/"},{default:o(()=>[...s[15]||(s[15]=[i("https://www.ostechnix.com/bootiso-lets-you-safely-create-bootable-usb-drive/",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=i("作者：",-1)),a(t,{href:"https://www.ostechnix.com/author/sk/"},{default:o(()=>[...s[17]||(s[17]=[i("SK",-1)])]),_:1}),s[22]||(s[22]=i(" 选题：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[18]||(s[18]=[i("lujun9972",-1)])]),_:1}),s[23]||(s[23]=i(" 译者：",-1)),a(t,{href:"https://github.com/kennethXia"},{default:o(()=>[...s[19]||(s[19]=[i("kennethXia",-1)])]),_:1}),s[24]||(s[24]=i(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:o(()=>[...s[20]||(s[20]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[27]||(s[27]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[25]||(s[25]=[i("LCTT",-1)])]),_:1}),s[28]||(s[28]=i(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:o(()=>[...s[26]||(s[26]=[i("Linux中国",-1)])]),_:1}),s[29]||(s[29]=i(" 荣誉推出",-1))])])}const S=n(b,[["render",h]]);export{B as __pageData,S as default};
